class DiscountPolicyTest {
    private final DiscountPolicy policy = new DiscountPolicy();

    @Test
    @DisplayName("10% off for orders above 100")
    void discountAboveOneHundred() {
        assertEquals(new BigDecimal("18.00"), policy.discountFor(new BigDecimal("180.00")));
    }

    @Test
    void rejectsNegativeTotals() {
        assertThrows(IllegalArgumentException.class,
                     () -> policy.discountFor(new BigDecimal("-1")));
    }
}

