import static org.assertj.core.api.Assertions.*;

@Test
void calculatesOrderTotal() {
    Order order = new Order(List.of(item("book", "50.00"), item("pen", "5.00")));

    assertThat(order.total()).isEqualByComparingTo("55.00");
    assertThat(order.items()).hasSize(2)
                             .extracting(Item::name)
                             .containsExactly("book", "pen");
}

